import type { Article, ArticleSection, Chapter, GlossaryTerm, RichText } from '../types';

const subjectId = 'fuehrung-zusammenarbeit';
const updatedAt = Date.UTC(2026, 10, 18);
const prefix = (id: string) => `fz-${id}`;
const term = (id: string, text: string): RichText => ({ text, termId: prefix(id) });
const link = (id: string, text: string): RichText => ({ text, articleId: prefix(id) });

const section = (id: string, title: string, ...paragraphs: (string | (RichText | string)[])[]): ArticleSection => ({
  id,
  title,
  paragraphs: paragraphs.map(paragraph => typeof paragraph === 'string'
    ? [{ text: paragraph }]
    : paragraph.map(part => typeof part === 'string' ? { text: part } : part)),
});
const exercise = (id: string, title: string, question: string, answer: string): ArticleSection => ({
  ...section(id, title, question),
  hint: { title: 'Musterantwort', content: answer },
});
const check = (question: string, answer: string): ArticleSection =>
  exercise('transfer', 'Selbstkontrolle und Transfer', question, answer);

interface Lesson {
  id: string;
  parent?: string;
  number: string;
  title: string;
  intro: string;
  sections: ArticleSection[];
}

